class Solution {
    public String nearestPalindromic(String n) {
        int len = n.length();
        long num = Long.parseLong(n);
        java.util.Set<Long> candidates = new java.util.HashSet<>();
        candidates.add((long) Math.pow(10, len - 1) - 1);
        candidates.add((long) Math.pow(10, len) + 1);
        long half = Long.parseLong(n.substring(0, (len + 1) / 2));
        for (long h = half - 1; h <= half + 1; h++) {
            String hs = String.valueOf(h);
            StringBuilder sb = new StringBuilder(hs);
            for (int i = len / 2 - 1; i >= 0; i--) sb.append(hs.charAt(i));
            candidates.add(Long.parseLong(sb.toString()));
        }
        candidates.remove(num);
        long closest = -1;
        for (long c : candidates) {
            if (closest == -1 || Math.abs(c - num) < Math.abs(closest - num) ||
                (Math.abs(c - num) == Math.abs(closest - num) && c < closest)) {
                closest = c;
            }
        }
        return String.valueOf(closest);
    }
}

class Solution {
    public String nearestPalindromic(String n) {
        int len = n.length();
        long num = Long.parseLong(n);
        long[] candidates = new long[5];
        candidates[0] = (long) Math.pow(10, len - 1) - 1;
        candidates[1] = (long) Math.pow(10, len) + 1;
        long halfVal = Long.parseLong(n.substring(0, (len + 1) / 2));
        long[] halfOptions = {halfVal - 1, halfVal, halfVal + 1};
        for (int idx = 0; idx < 3; idx++) {
            String hs = String.valueOf(halfOptions[idx]);
            StringBuilder sb = new StringBuilder(hs);
            int start = len / 2 - 1;
            for (int i = start; i >= 0; i--) {
                sb.append(hs.charAt(i));
            }
            candidates[idx + 2] = Long.parseLong(sb.toString());
        }
        long best = -1;
        for (int i = 0; i < 5; i++) {
            if (candidates[i] == num) continue;
            if (best == -1
                || Math.abs(candidates[i] - num) < Math.abs(best - num)
                || (Math.abs(candidates[i] - num) == Math.abs(best - num) && candidates[i] < best)) {
                best = candidates[i];
            }
        }
        return String.valueOf(best);
    }
}
